template.solver:
def solve(i1, p, q):
    i2 = p / q
    k = 2 * (i2 - i1) / (2 * i1 - i2)
    best = 0
    for n in range(1, 5):
        for m in range(1, 5):
            if n * m <= 4:
                cur = n * i1 * (k + 1) / (k + n / m)
                if cur > best:
                    best = cur
    return best
